117: // validateTraversalRecursion determines from the ResolverMeta.TraversalBloom value if a traversal loop has happened
118: // based on the argument key. As a bloom filter, this may lead to false positives,
119: // so clients should take that into account.
120: func validateTraversalRecursion(meta *v1.ResolverMeta, key string) ([]byte, error) {
121: 	if len(meta.TraversalBloom) == 0 {
122: 		return nil, status.Error(codes.Internal, fmt.Errorf("required traversal bloom filter is missing").Error())
123: 	}
124: 
125: 	bf := &bloom.BloomFilter{}
126: 	if err := bf.UnmarshalBinary(meta.TraversalBloom); err != nil {
127: 		return nil, status.Error(codes.Internal, fmt.Errorf("unable to unmarshall traversal bloom filter: %w", err).Error())
128: 	}
129: 
130: 	if bf.TestString(key) {
131: 		return nil, ErrLoopDetect
132: 	}
133: 
134: 	bf = bf.AddString(key)
135: 	modifiedBloomFilter, err := bf.MarshalBinary()
136: 	if err != nil {
137: 		return nil, err
138: 	}
139: 
140: 	return modifiedBloomFilter, nil
141: }
